package frb.axeron.manager.ui.util

/**
 * One APK asset listed by a GitHub release.
 */
internal data class ReleaseApkAsset(
    val name: String,
    val downloadUrl: String
)

internal data class SelectedReleaseApk(
    val versionCode: Int,
    val downloadUrl: String
)

// Matches the APK names generated by manager/build.gradle.kts.
// Other release assets (for example demo APKs) are not app updates.
private val releaseApkName = Regex(
    """^AxManager_v.+?_(\d+)-release-(arm64-v8a|armeabi-v7a|x86_64|universal)(?:_[^/]*)?\.apk$""",
    RegexOption.IGNORE_CASE
)

/**
 * Prefer the first device-supported ABI; use the universal APK only as a fallback.
 * Returns null if the release does not contain a compatible AxManager APK.
 */
internal fun selectReleaseApk(
    assets: List<ReleaseApkAsset>,
    supportedAbis: List<String>
): SelectedReleaseApk? {
    for (abi in supportedAbis + "universal") {
        for (asset in assets) {
            val match = releaseApkName.matchEntire(asset.name) ?: continue
            if (!match.groupValues[2].equals(abi, ignoreCase = true)) continue
            val versionCode = match.groupValues[1].toIntOrNull() ?: continue
            return SelectedReleaseApk(versionCode, asset.downloadUrl)
        }
    }
    return null
}
